blocks.code:
$brand: #3451b2;
$space: (
  sm: 0.5rem,
  md: 1rem,
  lg: 1.5rem
 );

@use 'sass:map';

.card {
  color: $brand;
  padding: map.get($space, md);
  &__title { margin-bottom: map.get($space, sm); }
  &:hover { border-color: darken($brand, 8%); }
}

blocks.starterCode:
$brand: #3451b2;

// TODO: move shared values to _tokens.scss and load with @use.
.page {
  .panel {
    .title { color: $brand; }
  }
}

